var a=244;var i=[{id:`cooking-244-01`,theoryId:244,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Which ingredient combination best illustrates a common Greek/Mediterranean approach?`,ua:`Яке поєднання найкраще ілюструє поширений грецький та середземноморський підхід?`},explanation:{en:`This is one useful pattern, not a universal rule for all Mediterranean regions.`,ua:`Це одна з характерних моделей, а не універсальне правило для всіх середземноморських регіонів.`},options:[{id:`a`,text:{en:`Olive oil, legumes, vegetables and herbs`,ua:`Оливкова олія, бобові, овочі та зелень`}},{id:`b`,text:{en:`Only cream, butter and sugar`,ua:`Лише вершки, масло та цукор`}},{id:`c`,text:{en:`An identical spice mix for every dish`,ua:`Однакова суміш спецій для всіх страв`}}],answer:{optionIds:[`a`]}},{id:`cooking-244-02`,theoryId:244,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Mediterranean food traditions are culturally identical across all coastal countries.`,ua:`Середземноморські кулінарні традиції культурно однакові в усіх прибережних країнах.`},explanation:{en:`Ingredients and practices vary substantially across coastal communities.`,ua:`Інгредієнти та практики суттєво відрізняються між прибережними громадами.`},answer:{value:!1}},{id:`cooking-244-03`,theoryId:244,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match an ingredient to a useful culinary function.`,ua:`Поєднайте інгредієнт із його кулінарною функцією.`},explanation:{en:`Balance depends on acidity, fat, texture and the rest of the dish.`,ua:`Баланс залежить від кислоти, жиру, текстури та решти компонентів.`},leftItems:[{id:`l1`,text:{en:`Lemon juice`,ua:`Лимонний сік`}},{id:`l2`,text:{en:`Olive oil`,ua:`Оливкова олія`}},{id:`l3`,text:{en:`Chickpeas`,ua:`Нут`}}],rightItems:[{id:`r2`,text:{en:`Provides fat and aroma`,ua:`Додає жир та аромат`}},{id:`r3`,text:{en:`Adds legume protein and body`,ua:`Додає бобовий білок та густину`}},{id:`r1`,text:{en:`Adds acidity and brightness`,ua:`Додає кислотності та свіжості смаку`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-244-04`,theoryId:244,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A lemon-and-olive-oil dressing tastes extremely sour. What is the best first adjustment?`,ua:`Заправка з лимонного соку та оливкової олії надто кисла. Що зробити насамперед?`},explanation:{en:`A vinaigrette is tuned through its oil, acid and seasoning balance.`,ua:`Баланс заправки визначають олія, кислота та приправи.`},options:[{id:`a`,text:{en:`Boil for an hour`,ua:`Кип’ятити годину`}},{id:`b`,text:{en:`Adjust the fat-to-acid ratio and taste again`,ua:`Скоригувати співвідношення жиру та кислоти й скуштувати знову`}},{id:`c`,text:{en:`Throw in raw flour`,ua:`Всипати сире борошно`}}],answer:{optionIds:[`b`]}},{id:`cooking-244-05`,theoryId:244,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which statements reflect thoughtful regional cooking?`,ua:`Які твердження відображають уважний підхід до регіональної кухні?`},explanation:{en:`A regional framework is a starting point, not a rigid recipe.`,ua:`Регіональний підхід є відправною точкою, а не жорстким рецептом.`},options:[{id:`a`,text:{en:`Assume Greek and Moroccan food are identical`,ua:`Вважати грецьку та марокканську кухні однаковими`}},{id:`b`,text:{en:`Balance acidity and olive oil purposefully`,ua:`Свідомо балансувати кислотність та оливкову олію`}},{id:`c`,text:{en:`Consider seasonal vegetables`,ua:`Враховувати сезонні овочі`}},{id:`d`,text:{en:`Learn traditional methods as well as ingredients`,ua:`Вивчати традиційні методи разом з інгредієнтами`}}],answer:{optionIds:[`d`,`c`,`b`]}},{id:`cooking-244-06`,theoryId:244,type:`sequence`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Put these salad-preparation actions in a sensible order.`,ua:`Розташуйте дії приготування салату в логічній послідовності.`},explanation:{en:`Dry greens hold dressing better; late dressing helps preserve texture.`,ua:`Суха зелень краще утримує заправку; пізнє заправляння зберігає текстуру.`},steps:[{id:`s4`,text:{en:`Taste, adjust and serve`,ua:`Скуштувати, скоригувати та подати`}},{id:`s1`,text:{en:`Wash and dry the greens`,ua:`Помити й обсушити зелень`}},{id:`s2`,text:{en:`Prepare and measure dressing components`,ua:`Підготувати та відміряти компоненти заправки`}},{id:`s3`,text:{en:`Toss greens shortly before serving`,ua:`Заправити зелень незадовго до подачі`}}],answer:{order:[`s1`,`s2`,`s3`,`s4`]}}];var n={theoryId:244,exercises:i};export{n as default,i as exercises,a as theoryId};